#!/usr/bin/env node
/**
 * Regenerate src/lib/tool-category.ts from the catalogue.
 *
 *   npm run build:categories
 *
 * The file this writes is a union of every category string the catalogue
 * actually uses. It exists so a thirty-eighth near-variant is a compile error
 * rather than a silent near-miss that matches nothing anyone would guess.
 *
 * Committed because the first version of this ran once and was deleted, leaving
 * the generated file with a comment telling the next person to "regenerate"
 * using a one-liner that printed a newline-separated list — not the union
 * syntax the file is written in. An instruction that does not reproduce the
 * artefact is worse than none: it looks like a path and ends in hand-editing
 * thirty-seven lines.
 *
 * `tool-category.test.mjs` fails if the committed file drifts from the
 * catalogue, so forgetting to run this is caught rather than shipped.
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { tools } from "../src/lib/catalog.ts";

const projectRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const used = [...new Set(tools.map((tool) => tool.category))].sort();

const header = `/**
 * The search keywords a model can be filed under.
 *
 * This is not the library's taxonomy, and collapsing it would be a mistake.
 * The Library groups by \`contract.domain\`; nothing on the site renders
 * \`category\` at all. Its single consumer is \`searchableToolText\`, so each of
 * these strings exists to be *typed into the search box* and matched.
 *
 * That is why there are ${used.length} of them and why several look like
 * near-duplicates. "Fasteners" and "Machine elements" overlap as taxonomy and
 * do not overlap as search terms: someone hunting a bolt calculation types one
 * or the other, and merging them deletes a word people search for. The only
 * merge worth making was "Fluids & thermal" into "Thermal & fluids" -- the same
 * two words in the other order, which is one keyword typed twice rather than
 * two keywords.
 *
 * A union rather than \`string\` so a thirty-eighth variant is a compile error
 * instead of a silent near-miss that matches nothing anyone would guess. To add
 * a genuinely new keyword, add it to a model in the catalogue and regenerate.
 *
 * Generated by scripts/build-tool-categories.mjs — do not edit by hand:
 *
 *   npm run build:categories
 *
 * \`tool-category.test.mjs\` fails if this drifts from the catalogue.
 */
export type ToolCategory =
`;

const body = used.map((category) => `  | ${JSON.stringify(category)}`).join("\n");
writeFileSync(join(projectRoot, "src/lib/tool-category.ts"), `${header}${body};\n`);
console.log(`build-tool-categories: ${used.length} categories -> src/lib/tool-category.ts`);
